#!/usr/bin/env python3
"""Render references/catalog.md (human-readable measure catalog) from the YAML sources.

Usage: python3 scripts/render_catalog.py
"""

from __future__ import annotations

import sys

from semantic_core import REFS, load_catalog


def _cell(text) -> str:
    return " ".join(str(text or "").split()).replace("|", "\\|")


def render() -> str:
    cat = load_catalog()
    lines = ["# Energy measure catalog", "",
             "Generated by `scripts/render_catalog.py` from `measure_catalog/*.yaml`. Do not edit.", "",
             f"{len(cat.measures)} measures across {len(cat.metric_views)} metric views.", ""]
    for mv, info in sorted(cat.metric_views.items()):
        lines += [f"## `{mv}`", "", f"Entity `{info['entity']}` · domain `{info['domain']}`", "",
                  "| Measure | Type | Unit | Expression | Definition |",
                  "|---------|------|------|------------|------------|"]
        for m in cat.measures_for(mv):
            lines.append(f"| `{m['name']}` | {m['type']} | {_cell(m['unit'])} | "
                         f"`{_cell(m['expr'])}` | {_cell(m['definition'])} |")
        lines.append("")
    return "\n".join(lines)


def main() -> int:
    (REFS / "catalog.md").write_text(render(), encoding="utf-8")
    print(f"wrote {REFS / 'catalog.md'}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
